# Generates ffmpeg-playground/src/swscale.rs: hscale, input, range_convert,
# yuv2plane1 and rgb2rgb.
import re, sys
ex = {l.split("\t")[1].strip(): l.split("\t")[0].split("aarch64_")[1] + ".S" for l in open(sys.argv[1]) if "libswscale" in l.split("\t")[0]}
out = ['''//! libswscale/aarch64 hscale.S, input.S, range_convert_neon.S, output.S
//! (yuv2plane1) and rgb2rgb_neon.S. Generated by gen/swscale.py.
//!
//! hscale: dstW outputs, output i reading filterSize source samples from
//! filterPos[i]; initFilter keeps every position within the line
//! (filterPos[..] <= srcW - filterSize). 8-to-19 and 16-bit outputs are
//! int32. input: one line of w pixels into int16 Y (or U/V; _half reads 2w
//! pixels); rgb2yuv is the context's 176-entry table. Input lines are
//! exactly as long as the pixels they hold. The lines between the horizontal
//! and vertical scalers (hscale output, range convert, yuv2plane*/nv12cX
//! input) are slice.c's: FFALIGN(dst_w * 2 + 66, 16) bytes, scaled with the
//! sample size, so at least dst_w + 33 samples; the NEON code works in whole
//! vectors past dst_w. initFilter allocates filterPos and the filter for
//! dstW + 3 outputs, copying filterPos[dstW - 1] into the three extra entries.
use bums_macros as bums;
''']
def emit(name, args, pre, sig):
    if name not in ex:
        print("missing", name, file=sys.stderr); return
    out.append(f'''#[bums::check_mem_safe("{ex[name]}", {", ".join(args)},
    [{", ".join(pre)}])]
fn {name}({sig});
''')
for name in sorted(ex):
    m = re.match(r"ff_hscale(8|16)to(15|19)_(4|X4|X8)_neon(_asm)?$", name)
    if m:
        src_bits, dst_bits, kind, wrapped = m.group(1), m.group(2), m.group(3), bool(m.group(4))
        sty = "u8" if src_bits == "8" else "u16"
        dty = "i16" if (dst_bits == "15") else "i32"
        fs = {"4": ["filter_size == 4"], "X4": ["filter_size % 4 == 0", "filter_size % 8 != 0", "filter_size >= 4"],
              "X8": ["filter_size % 8 == 0", "filter_size >= 8"]}[kind]
        first, firstsig = ("shift", "shift: i32") if wrapped else ("ctx.as_ptr()", "ctx: &[u8]")
        pre = ([] if wrapped else ["ctx.len() == 1"]) + [
            "dst.len() == dst_w + 33", "dst_w >= 1", "dst_w <= 16384", "src.len() == src_w", "src_w >= filter_size", "src_w <= 16384",
            "filter.len() == (dst_w + 3) * filter_size", "filter_pos.len() == dst_w + 3", "filter_pos[..] <= (src_w - filter_size) as i32",
            "filter_pos[..] >= 0", "filter_size <= 256"] + fs
        emit(name, [first, "dst.as_mut_ptr()", "dst_w", "src.as_ptr()", "filter.as_ptr()", "filter_pos.as_ptr()", "filter_size"], pre,
             f"{firstsig}, dst: &mut [{dty}], dst_w: usize, src: &[{sty}], filter: &[i16], filter_pos: &[i32], filter_size: usize, src_w: usize")
        continue
    m = re.match(r"ff_(rgb24|bgr24|rgba32|bgra32|argb32|abgr32)To(Y|UV|UV_half)_neon(_dotprod)?$", name)
    if m:
        fmt, kind = m.group(1), m.group(2)
        bpp = 3 if "24" in fmt else 4
        per = 2 * bpp if kind == "UV_half" else bpp
        if kind == "Y":
            emit(name, ["dst.as_mut_ptr()", "src.as_ptr()", "unused1.as_ptr()", "unused2.as_ptr()", "w", "rgb2yuv.as_ptr()", "opaque.as_ptr()"],
                 ["dst.len() == w", f"src.len() == {per} * w", "unused1.len() == 1", "unused2.len() == 1", "w >= 1", "w <= 16384",
                  "rgb2yuv.len() == 176", "opaque.len() == 1"],
                 "dst: &mut [i16], src: &[u8], unused1: &[u8], unused2: &[u8], w: usize, rgb2yuv: &[i32], opaque: &[u8]")
        else:
            emit(name, ["dst_u.as_mut_ptr()", "dst_v.as_mut_ptr()", "unused0.as_ptr()", "src1.as_ptr()", "src2.as_ptr()", "w", "rgb2yuv.as_ptr()", "opaque.as_ptr()"],
                 ["dst_u.len() == w", "dst_v.len() == w", "unused0.len() == 1", f"src1.len() == {per} * w", f"src2.len() == {per} * w", "w >= 1", "w <= 16384",
                  "rgb2yuv.len() == 176", "opaque.len() == 1"],
                 "dst_u: &mut [i16], dst_v: &mut [i16], unused0: &[u8], src1: &[u8], src2: &[u8], w: usize, rgb2yuv: &[i32], opaque: &[u8]")
        continue
    m = re.match(r"ff_(lum|chr)Range(From|To)Jpeg(8|16)_neon$", name)
    if m:
        lum, bits = m.group(1) == "lum", m.group(3)
        ty = "i16" if bits == "8" else "i32"
        if lum:
            emit(name, ["dst.as_mut_ptr()", "width", "coeff", "offset"], ["dst.len() == width + 33", "width >= 1", "width <= 16384"],
                 f"dst: &mut [{ty}], width: usize, coeff: u32, offset: i64")
        else:
            emit(name, ["dst_u.as_mut_ptr()", "dst_v.as_mut_ptr()", "width", "coeff", "offset"],
                 ["dst_u.len() == width + 33", "dst_v.len() == width + 33", "width >= 1", "width <= 16384"],
                 f"dst_u: &mut [{ty}], dst_v: &mut [{ty}], width: usize, coeff: u32, offset: i64")
        continue
    m = re.match(r"ff_shuffle_bytes_\d{4}_neon$", name)
    if m:
        emit(name, ["src.as_ptr()", "dst.as_mut_ptr()", "src_size"],
             ["src.len() == src_size", "dst.len() == src_size", "src_size % 4 == 0", "src_size >= 4", "src_size <= 1073741824"],
             "src: &[u8], dst: &mut [u8], src_size: usize")
        continue
    conv = {"ff_rgb24tobgr24_neon": (3, 3), "ff_rgb32tobgr24_neon": (4, 3), "ff_rgb24tobgr32_neon": (3, 4)}
    if name in conv:
        a, b = conv[name]
        emit(name, ["src.as_ptr()", "dst.as_mut_ptr()", "src_size"],
             [f"src.len() == src_size", f"dst.len() == src_size / {a} * {b}", f"src_size % {a} == 0", f"src_size >= {a}", "src_size <= 1073741824"],
             "src: &[u8], dst: &mut [u8], src_size: usize")
        continue
    if name == "ff_interleave_bytes_neon":
        emit(name, ["src1.as_ptr()", "src2.as_ptr()", "dest.as_mut_ptr()", "width", "height", "s1", "s2", "ds"],
             ["src1.len() == (height - 1) * s1 + width", "src2.len() == (height - 1) * s2 + width", "dest.len() == (height - 1) * ds + 2 * width",
              "s1 >= width", "s2 >= width", "ds >= 2 * width", "s1 <= 1073741824", "s2 <= 1073741824", "ds <= 1073741824",
              "width >= 1", "width <= 16384", "height >= 1", "height <= 16384"],
             "src1: &[u8], src2: &[u8], dest: &mut [u8], width: usize, height: usize, s1: usize, s2: usize, ds: usize")
        continue
    if name == "ff_deinterleave_bytes_neon":
        emit(name, ["src.as_ptr()", "dst1.as_mut_ptr()", "dst2.as_mut_ptr()", "width", "height", "ss", "d1", "d2"],
             ["src.len() == (height - 1) * ss + 2 * width", "dst1.len() == (height - 1) * d1 + width", "dst2.len() == (height - 1) * d2 + width",
              "ss >= 2 * width", "d1 >= width", "d2 >= width", "ss <= 1073741824", "d1 <= 1073741824", "d2 <= 1073741824",
              "width >= 1", "width <= 16384", "height >= 1", "height <= 16384"],
             "src: &[u8], dst1: &mut [u8], dst2: &mut [u8], width: usize, height: usize, ss: usize, d1: usize, d2: usize")
        continue
    m = re.match(r"ff_(uyvy|yuyv)toyuv(420|422)_neon$", name)
    if m:
        ch_rows = "height / 2" if m.group(2) == "420" else "height"
        emit(name, ["ydst.as_mut_ptr()", "udst.as_mut_ptr()", "vdst.as_mut_ptr()", "src.as_ptr()", "width", "height", "lum", "chrom", "ss"],
             ["ydst.len() == (height - 1) * lum + width", f"udst.len() == ({ch_rows} - 1) * chrom + width / 2", f"vdst.len() == ({ch_rows} - 1) * chrom + width / 2",
              "src.len() == (height - 1) * ss + 2 * width", "width % 2 == 0", "width >= 2", "width <= 16384",
              "height % 2 == 0", "height >= 2", "height <= 16384", "lum >= width", "chrom >= width / 2", "ss >= 2 * width",
              "lum <= 1073741824", "chrom <= 1073741824", "ss <= 1073741824"],
             "ydst: &mut [u8], udst: &mut [u8], vdst: &mut [u8], src: &[u8], width: usize, height: usize, lum: usize, chrom: usize, ss: usize")
        continue
    if name == "ff_rgb24toyv12_neon":
        emit(name, ["src.as_ptr()", "ydst.as_mut_ptr()", "udst.as_mut_ptr()", "vdst.as_mut_ptr()", "width", "height", "lum", "chrom", "ss", "rgb2yuv.as_ptr()"],
             ["src.len() == (height - 1) * ss + 3 * width", "ydst.len() == (height - 1) * lum + width",
              "udst.len() == (height / 2 - 1) * chrom + width / 2", "vdst.len() == (height / 2 - 1) * chrom + width / 2",
              "width % 16 == 0", "width >= 16", "width <= 16384", "height % 2 == 0", "height >= 2", "height <= 16384",
              "lum >= width", "chrom >= width / 2", "ss >= 3 * width", "lum <= 1073741824", "chrom <= 1073741824", "ss <= 1073741824",
              "rgb2yuv.len() == 176"],
             "src: &[u8], ydst: &mut [u8], udst: &mut [u8], vdst: &mut [u8], width: usize, height: usize, lum: usize, chrom: usize, ss: usize, rgb2yuv: &[i32]")
        continue
    if name == "ff_yuv2plane1_8_neon":
        emit(name, ["src.as_ptr()", "dest.as_mut_ptr()", "dst_w", "dither.as_ptr()", "offset"],
             ["src.len() == dst_w + 33", "dest.len() == dst_w", "dst_w >= 1", "dst_w <= 16384", "dither.len() == 8", "offset <= 7"],
             "src: &[i16], dest: &mut [u8], dst_w: usize, dither: &[u8], offset: usize")
        continue
    print("skip", name, file=sys.stderr)
out.append(open(__import__("os").path.join(__import__("os").path.dirname(__file__), "..", "extra", "swscale.rs")).read().strip("\n") + "\n")  # hand-written tail
print("\n".join(out))
